SetFunctionName("Sqt(const Sqt&)");
Sqt sqtRef(5.0f, 6.0f, 7.0f, 1.0f, 2.1f, 3.2f, 4.3f, 5.0f, 6.0f, 7.0f );
Sqt sqt(sqtRef);
Validate((float)sqt.GetScale().X() == 5.0f && (float)sqt.GetScale().Y() == 6.f && (float)sqt.GetScale().Z() == 7.f 
&& (float)sqt.GetQuaternion().X() == 1.0f && (float)sqt.GetQuaternion().Y() == 2.1f && (float)sqt.GetQuaternion().Z() == 3.2f && (float)sqt.GetQuaternion().W() == 4.3f
&& (float)sqt.GetTranslation().X() == 5.0f && (float)sqt.GetTranslation().Y() == 6.f && (float)sqt.GetTranslation().Z() == 7.f);



SetFunctionName("Sqt(Vector3 scale, Quaternion quat, Vector3 trans)");
