Quaternion q(1.0f, 2.0f, 3.0f, 4.0f);
Vector3 p(5.0f, 6.0f, 7.0f);
Sqt sqt(s, q, p);

Validate( sqt.GetScale() == s &&
          sqt.GetQuaternion() == q &&
          sqt.GetTranslation() == p );



