SetFunctionName("Sqt Select(MaskScalar mask, Sqt a, Sqt b)");
const Sqt sqt1(5.1f, 6.1f, 7.1f, 1.0f, 2.0f, 3.0f, 4.0f, 5.0f, 6.0f, 7.0f);
const Sqt sqt2(15.1f, 16.1f, 17.1f, 12.0f, 12.0f, 13.0f, 14.0f, 15.0f, 16.0f, 17.0f);

Sqt result1 = Select( MaskScalar(true), sqt1, sqt2 );
Sqt result2 = Select( MaskScalar(false), sqt1, sqt2 );
Validate(
    result1 == sqt1 &&
    result2 == sqt2
);



SetFunctionName("IsSimilar(Sqt a,  Sqt b, epsilon)");
Sqt sqt1(5.0f, 6.0f, 7.0f, 1.0f, 2.0f, 3.0f, 4.0f, 5.0f, 6.0f, 7.0f );
Sqt sqt2(5.0f, 6.0f, 7.1f, 1.0f, 2.0f, 3.0f, 4.1f, 5.0f, 6.0f, 7.1f );

Validate( !IsSimilar(sqt1, sqt2) &&
          !IsSimilar(sqt1, sqt2, (float_test_type)0.09f) &&
           IsSimilar(sqt1, sqt2, (float_test_type)0.11f) );



// on SPU, NaN operations evaluates to 0
#if !defined EA_PLATFORM_PS3_SPU
        {
            SetFunctionName("IsValid(Sqt a,  Sqt b, epsilon)");
            float nan = (float)testing::GetNaN();
            Sqt sqt1(5.0f, 6.0f, 7.0f, 1.0f, 2.0f, 3.0f, 4.0f, 5.0f, 6.0f, 7.0f );

            Sqt sqt2(5.0f, 6.0f, 7.01f, nan, 2.0f, 3.0f, 4.0f, 5.0f, 6.0f, 7.01f );
            Sqt sqt3(5.0f, 6.0f, 7.01f, 1.0f, 2.0f, 3.0f, 4.0f, 5.0f, 6.0f, nan );
            Sqt sqt4(nan, 6.0f, 7.01f, 1.0f, 2.0f, 3.0f, 4.0f, 5.0f, 6.0f, 7.0f );

            Validate(  IsValid(sqt1) &&
                      !IsValid(sqt2) &&
                      !IsValid(sqt3) &&
                      !IsValid(sqt4) );
        }
#endif



SetFunctionName("Mult(Sqt a, Sqt b)");
Sqt sqt1( 1.1f, 1.2f, 1.3f, 0.0f, -0.7071068f, 0.0f, 0.7071068f, 1.0f, 2.0f, 3.0f);
Sqt sqt2( 1.0f, 1.5f, 1.0f, -0.5f, 0.5f, -0.5f, 0.5f, 5.0f, 0.0f, 0.0f );
// Note: These numbers were generated by running Mult on the input.
// This test case will only ensure future changes don't modify the results generated.
Sqt ref( 1.1f, 1.8f, 1.3f, 0.0f, 0.0f, -0.7071068f, 0.7071068f, 1.0f, 2.0f, 8.5f );

Sqt result = Mult(sqt2, sqt1);

Validate( IsSimilar( result, ref, (float_test_type)0.001f ) );



SetFunctionName("Mult(Sqt a, QuatPos b)");

Sqt sqt( 1.1f, 1.2f, 1.3f, 0.0f, -0.7071068f, 0.0f, 0.7071068f, 1.0f, 2.0f, 3.0f);
QuatPos qp( -0.5f, 0.5f, -0.5f, 0.5f, 5.0f, 0.0f, 0.0f );
// Note: These numbers were generated by running Mult on the input.
// This test case will only ensure future changes don't modify the results generated.
Sqt ref( 1.1f, 1.2f, 1.3f, 0.0f, 0.0f, -0.7071068f, 0.7071068f, 1.0f, 2.0f, 8.5f );

Sqt result = Mult(sqt, qp);

Validate( IsSimilar( result, ref, (float_test_type)0.001f ) );




SetFunctionName("Inverse(Sqt a)");

Sqt sqt( 1.1f, 1.2f, 1.3f, 0.0f, -0.7071068f, 0.0f, 0.7071068f, 1.0f, 2.0f, 3.0f);
Sqt sqtInv = Inverse(sqt);
Sqt multiply_sqt_sqtInv = Mult(sqt, sqtInv);

Sqt sqt_compare;
sqt_compare.quat = Conj(sqt.quat);
sqt_compare.scale = Reciprocal(sqt.scale);
sqt_compare.trans = -TransformVector(Mult(sqt.trans, sqt_compare.scale), sqt_compare.quat);

Sqt sqt_identity;
sqt_identity.SetIdentity();

Validate(
        IsEqualWithEpsilon((float_basic_type)sqtInv.scale.X(), (float_basic_type)sqt_compare.scale.X()) &&
        IsEqualWithEpsilon((float_basic_type)sqtInv.scale.Y(), (float_basic_type)sqt_compare.scale.Y()) &&
        IsEqualWithEpsilon((float_basic_type)sqtInv.scale.Z(), (float_basic_type)sqt_compare.scale.Z()) &&
        IsEqualWithEpsilon((float_basic_type)sqtInv.quat.X(), (float_basic_type)sqt_compare.quat.X()) &&
        IsEqualWithEpsilon((float_basic_type)sqtInv.quat.Y(), (float_basic_type)sqt_compare.quat.Y()) &&
        IsEqualWithEpsilon((float_basic_type)sqtInv.quat.Z(), (float_basic_type)sqt_compare.quat.Z()) &&
        IsEqualWithEpsilon((float_basic_type)sqtInv.quat.W(), (float_basic_type)sqt_compare.quat.W()) &&
        IsEqualWithEpsilon((float_basic_type)sqtInv.trans.X(), (float_basic_type)sqt_compare.trans.X()) &&
        IsEqualWithEpsilon((float_basic_type)sqtInv.trans.Y(), (float_basic_type)sqt_compare.trans.Y()) &&
        IsEqualWithEpsilon((float_basic_type)sqtInv.trans.Z(), (float_basic_type)sqt_compare.trans.Z()) &&
        IsSimilar( multiply_sqt_sqtInv, sqt_identity, (float_test_type)0.001f )
);



SetFunctionName("SqtFromMatrix44(Matrix44::InParam)");

Matrix44 inputM(
    -1.8901101f,       2.3296704f,     0.010989010f,      0.00000000f,
    -1.5238097f,      -1.2380955f,      0.38095242f,      0.00000000f,
    0.15018317f,      0.11721613f,      0.98168498f,      0.00000000f,
     1.0000000f,       2.0000000f,       3.0000000f,       1.0000000f
);

Sqt sqt = SqtFromMatrix44(inputM);
Vector3 s(3.0f, 2.0f, 1.0f);
Quaternion q = Normalize(Quaternion(0.1f, 0.2f, 2.1f, 1.0f));
Vector3 t(1.0f, 2.0f, 3.0f);

Validate( IsSimilar( sqt.GetScale(), s, (float_test_type)0.001f) &&
          IsSimilar( sqt.GetQuaternion(), q, (float_test_type)0.001f ) &&
