SetFunctionName("Lerp(Sqt::InParam, Sqt::InParam, VecFloat::InParam)");

Sqt sqtFrom = Sqt(Vector3(1.0f, 2.0f, -3.9f), Quaternion(1.0f, 2.0f, 3.45f, 2.1f), Vector3(1.0f, 2.0f, -3.9f));
Sqt sqtTo = Sqt(Vector3(-3.0f, 1.0f, 2.3f), Quaternion(-3.0f, 1.0f, 5.3f, 2.1f), Vector3(-3.0f, 1.0f, 2.3f));
Sqt sqt = Lerp(sqtFrom, sqtTo, (float_test_type)0.25f);

Validate(
    IsEqualWithEpsilon(sqt.scale.X(), (float_basic_type) 0.0f) &&
    IsEqualWithEpsilon(sqt.scale.Y(), (float_basic_type) 1.75f) &&
    IsEqualWithEpsilon(sqt.scale.Z(), (float_basic_type) -2.3500001f) &&
    IsEqualWithEpsilon(sqt.quat.X(), (float_basic_type) 0.0f) &&
    IsEqualWithEpsilon(sqt.quat.Y(), (float_basic_type) 1.75f) &&
    IsEqualWithEpsilon(sqt.quat.Z(), (float_basic_type) 3.9125001f) &&
    IsEqualWithEpsilon(sqt.quat.W(), (float_basic_type) 2.0999999f) &&
    IsEqualWithEpsilon(sqt.trans.X(), (float_basic_type) 0.0f) &&
    IsEqualWithEpsilon(sqt.trans.Y(), (float_basic_type) 1.75f) &&
    IsEqualWithEpsilon(sqt.trans.Z(), (float_basic_type) -2.3500001f)
    );



SetFunctionName("SLerp(Sqt::InParam, Sqt::InParam, VecFloat::InParam)");

Vector3 axis = Normalize(Vector3(1.0f, -1.0f, 0.05f));
Matrix44 from = Matrix44FromAxisRotationAngle( axis, (float_test_type)0.25f );
Matrix44 to = Matrix44FromAxisRotationAngle( axis, (float_test_type)0.75f );
Matrix44 ref = Matrix44FromAxisRotationAngle( axis, (float_test_type)0.5f );

Sqt sqtFrom = SqtFromMatrix44(from);
Sqt sqtTo = SqtFromMatrix44(to);
Sqt sqt = SLerp(sqtFrom, sqtTo, (float_test_type)0.5f);

Matrix44 m = Matrix44FromSqt(sqt);

Validate( IsSimilar(m, ref, (float_test_type)0.001f) );



SetFunctionName("Sqt&      operator = (Sqt::InParam v)");
Sqt sqtRef( 5.1f, 6.1f, 7.1f, 1.0f, 2.1f, 3.2f, 4.3f, 5.0f, 6.0f, 7.0f );
Sqt sqt;
sqt = sqtRef;
Validate((float)sqt.GetScale().X() == 5.1f && (float)sqt.GetScale().Y() == 6.1f && (float)sqt.GetScale().Z() == 7.1f &&
(float)sqt.GetQuaternion().X() == 1.0f && (float)sqt.GetQuaternion().Y() == 2.1f && (float)sqt.GetQuaternion().Z() == 3.2f && (float)sqt.GetQuaternion().W() == 4.3f
&& (float)sqt.GetTranslation().X() == 5.0f && (float)sqt.GetTranslation().Y() == 6.f && (float)sqt.GetTranslation().Z() == 7.f);



SetFunctionName("operator ==(Sqt::InParam a,           Sqt::InParam b)");
Sqt sqt1(5.1f, 6.1f, 7.1f, 1.0f, 2.0f, 3.0f, 4.0f, 5.0f, 6.0f, 7.0f );
Sqt sqt2(5.1f, 6.1f, 7.1f, 1.0f, 2.0f, 3.0f, 4.0f, 5.0f, 6.0f, 7.0f );
Sqt sqt3(5.0f, 6.0f, 7.0f, 1.0f, 2.0f, 3.0f, 4.0f, 5.0f, 6.0f, 7.0f );

Validate(   sqt1 == sqt2  &&
          !(sqt2 == sqt3) );



SetFunctionName("operator !=(Sqt::InParam a,           Sqt::InParam b)");
Sqt sqt1(5.1f, 6.1f, 7.1f, 1.0f, 2.0f, 3.0f, 4.0f, 5.0f, 6.0f, 7.0f );
Sqt sqt2(5.1f, 6.1f, 7.1f, 1.0f, 2.0f, 3.0f, 4.0f, 5.0f, 6.0f, 7.0f );
Sqt sqt3(5.0f, 6.0f, 7.0f, 1.0f, 2.0f, 3.0f, 4.0f, 5.0f, 6.0f, 7.0f );

Validate( !(sqt1 != sqt2) &&
            sqt2 != sqt3  );



